def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    # Initialize output grid with background 1s
    out = [[1] * cols for _ in range(rows)]

    for c in range(cols):
        vals = []
        color = None
        # Identify the dominant non-1 color (if any) for this column
        for r in range(rows):
            val = grid[r][c]
            if val != 1:
                if color is None:
                    color = val
                elif color != val:
                    color = None # Multiple colors implies noise/mix
                else:
                    vals.append(r)

        # If we found a consistent color, check for vertical adjacency
        if color is not None:
            is_adjacent = False
            for i in range(len(vals) - 1):
                if vals[i+1] == vals[i] + 1:
                    is_adjacent = True
                    break

            # If valid line found, fill the column with that color
            if is_adjacent:
                for r in range(rows):
                    out[r][c] = color

    return out
